\begin{theorem}
	\label{theorem:svrg}
    Suppose Assumptions~\ref{assumption:f-cvx}, \ref{assumption:phi-lowerbound}  and~\ref{assumption:g-lip-finite} hold for problem~\eqref{eqn:composite-finite}. Let the estimates $\tgkz$, $\tJkz$, $\tgki$ and $\tJki$ in Algorithm~\ref{algo:SVR-PL} be given in~\eqref{eqn:finite-gk0}-\eqref{eqn:J-svrg} respectively. If we choose $M\geq 4\ell_f L_g$ and $\tau = \bigl\lceil\frac{1}{2}N^{1/5}-1\bigr\rceil$, and
\[
    |\cB_i^k| = \bigr\lceil 4N^{4/5}\bigr\rceil, \qquad
    |\cS_i^k| = \bigr\lceil N^{2/5}\bigr\rceil, \qquad 
    i=1,\ldots,\tau-1,  \qquad k=1,\ldots,K,
\]
then the output of Algorithm~\ref{algo:SVR-PL} satisfies
\begin{equation}\label{eqn:cvg-svr-pl-nonsmooth-1}
    \E\bigl[\|\cG(x_{i^*}^{k^*})\|^2\bigr] ~\leq~ \frac{15M\bigl(\Phi(x_0^1) - \Phi_*\bigr)}{K\tau}.
\end{equation}
To get an $\epsilon$-stationary point in expectation, the total sample complexity for the component mappings $g_j$ and their Jacobians are both $\cO(N+N^{4/5}\epsilon^{-1})$.
\end{theorem}

