\begin{equation}
\label{eqn:composite-opt}
\minimize_{x\in\R^n} \quad f(g(x)) + h(x), 
\end{equation}

where $f:\R^m\rightarrow\R$ is a convex and possibly nonsmooth function, $g:\R^n\rightarrow\R^m$ is a smooth mapping (vector-valued function), and $h:\R^n\rightarrow\R$ is a convex and lower-semicontinuous function. 
Although both $f$ and $h$ are convex, the problem is in general nonconvex due to the composition of~$f$ and~$g$. 
In addition, we assume that~$g$ is either the average of finite number of component mappings, i.e., $g(x) = \frac{1}{N}\sum_{i=1}^N g_i(x)$, 
or the expectation of a family of random component mappings, i.e.,
$g(x) = \E_\xi [g_\xi(x)]$ where~$\xi$ is a random variable.
More explicitly, we consider the problems
\begin{equation}
\label{eqn:composite-finite}
\minimize_{x\in\R^n} \quad f\biggl(\frac{1}{N}\sum_{i=1}^N g_i(x)\biggr) + h(x)
\end{equation}

\begin{equation}\label{eqn:Phi-def}
\Phi(x) \triangleq f(g(x)) + h(x),
\end{equation}

\begin{assumption}\label{assumption:g-lip}
    The vector mapping $g:\R^n\to\R^m$ is $\ell_g$-Lipschitz continuous and its Jacobian $g':\R^n\to\R^{m\times n}$ is $L_g$-Lipschitz continuous, i.e., 
    \begin{align*}
        \|g(x) - g(y)\| &\leq \ell_g \|x-y\|, \\
        \|g'(x) - g'(y)\| &\leq L_g \|x-y\|, 
    \end{align*}
for all $x,y\in\dom h$, where $\|\cdot\|$ for matrices denotes the spectral norm.
\end{assumption}

A direct consequence of the Lipschitz condition on $g'$ in Assumption~\ref{assumption:g-lip} is 
\begin{equation}\label{eqn:g-quadratic-bd}
    \bigl\|g(x)-g(y)-g(y)'(x-y)\bigr\| \leq \frac{L_g}{2}\|x-y\|^2.
\end{equation}

\begin{assumption}\label{assumption:phi-lowerbound}
	There exists $\Phi_*$ such that  $\Phi_* = \inf_x\Phi(x)>-\infty$.
\end{assumption}

\begin{algorithm2e}[t]
    \caption{Stochastic variance-reduced prox-linear algorithm} %(framework)}
	\label{algo:SVR-PL} 
	{\bf input:} initial point $x^1_0$, $M>0$, number of outer and inner iterations $K$ and $\tau$.\\
	\For{$k = 1,\ldots,K$}{ 
		\For{$i = 0,\ldots,\tau-1$}{
            \eIf{$i==0$}{
                compute $\tgk_0$ and $\tJk_0$ using \emph{large} batches $\Bkz$ and $\Skz$ respectively. \label{alg-line:gk0-Jk0}
            }{
                compute $\tgki$ and $\tJki$ using \emph{small} batches $\Bki$ and $\Ski$ respectively. \label{alg-line:gki-Jki}
            }
            $\xkie = \displaystyle\argmin_x ~\textstyle\Bigl\{f\bigl(\tgki + \tJki(x-\xki)\bigr) + h(x) + \frac{M}{2}\|x-\xki\|^2\Bigr\}$. \label{alg-line:argmin}
		}
		Set $x_0^{k+1} = x^k_{\tau}.$
	}  
    {\bf output:} choose $x^{k^*}_{i^*}$ from $\{\xki\}_{i = 0,\ldots,\tau-1}^{k = 1,\ldots,K}$ uniformly at random.
\end{algorithm2e}

and the composite gradient mapping at~$x$,
\begin{equation}
\label{eqn:grad-mapping}
\cG_M(x)\triangleq M(x-x_+).
\end{equation}

The sample complexity of a randomized algorithm, such as Algorithm~\ref{algo:SVR-PL}, is the total number of evaluations of the component mappings $g_i$ or $g_\xi$ and their Jacobians required in order to output some $\bar{x}$ satisfying
\begin{equation}
\label{eqn:eps-solu}
\E\bigl[\|\cG(\bar{x})\|^2\bigr]\leq \epsilon,
\end{equation}

Notice that the proximal point $x_+$ used in the definition of $\cG(x)$ is computed with~$g(x)$ and~$g'(x)$, which can be very costly if not impossible to evaluate. 
In Algorithm~\ref{algo:SVR-PL}, the proximal point $\xkie$ is computed using the estimates $\tgki$ and $\tJki$, i.e.,
\begin{equation}\label{eqn:xkie-def}
    \xkie = \argmin_x \left\{f\bigl(\tgki + \tJki(x-\xki)\bigr) + h(x) + \frac{M}{2}\|x-\xki\|^2\right\}.
\end{equation}

This leads to a convenient approximation, 
\begin{equation}\label{eqn:approx-gm}
\widetilde{\cG}(\xki)\triangleq M(\xki-\xkie),
\end{equation}

of the true gradient mapping $\cGki= M(\xki-\hat{x}^k_{i+1})$, where 
\begin{equation}\label{eqn:x-hat-def}
    \hat{x}^k_{i+1} %= (\xki)_+
    = \argmin_x \left\{f\bigl(g(\xki) + g'(\xki)(x-\xki)\bigr) + h(x) + \frac{M}{2}\|x-\xki\|^2\right\}.
\end{equation}

In this section, we consider the composite finite-average problem~\eqref{eqn:composite-finite} with nonsmooth~$f$ and smooth~$g_i$'s.
In particular, we replace Assumption~\ref{assumption:g-lip} with the following more structured one, which implies Assumption~\ref{assumption:g-lip}.
\begin{assumption}
	\label{assumption:g-lip-finite}
    For each $i = 1,\ldots,N$, the mapping $g_i:\R^n\to\R^m$, is $\ell_{g,i}$-Lipschitz continuous and its Jacobian matrix $g'_i:\R^n\to\R^{m\times n}$ is $L_{g,i}$-Lipschitz continuous. Namely, 
\begin{align*}
\|g_i(x) - g_i(x)\| & \leq\ell_{g,i}\|x-y\|, \\
\|g'_i(x) - g'_i(x)\| & \leq L_{g,i}\|x-y\|,
\end{align*}
for all $x,y\in\dom h$ and $i = 1,\ldots,N$. 
\end{assumption}

A direct consequence of this assumption is that $g$ is $\big(\frac{1}{N}\sum_{i}^{N}\ell_{g,i}\big)$-Lipschitz continuous and $g'$ is $\big(\frac{1}{N}\sum_{i}^{N}L_{g,i}\big)$-Lipschitz continuous. Due to the root-mean square inequality $\frac{z_1+...+z_N}{N}\leq \sqrt{\frac{z_1^2+...+z_N^2}{N}}$, 
We define 
\begin{equation}\label{eqn:ms-Lip-constants}
\ell_g = \sqrt{\frac{1}{N}\sum_{i}^{N}\ell_{g,i}^2}, \qquad
L_g = \sqrt{\frac{1}{N}\sum_{i}^{N}L_{g,i}^2},
\end{equation}

In this case, we construct the estimates $\tgkz$ and $\tJkz$ using the full batch. In other words, we let $\Bkz=\Skz=\{1,2,\ldots,N\}$ and replace Line~\ref{alg-line:gk0-Jk0} in Algorithm~\ref{algo:SVR-PL} with
\begin{eqnarray}
\tgkz &=& g(\xkz) = \frac{1}{N}\sum_{i=1}^N g_i(\xkz), 
    \label{eqn:finite-gk0} \\
    \tJkz &=& g'(\xkz) = \frac{1}{N}\sum_{i=1}^N g'_i(\xkz).
    \label{eqn:finite-Jk0}
\end{eqnarray}

For $i>0$, we sample with replacement from $\{1,2,\ldots,N\}$ to obtain smaller sets $\Bki$ and $\Ski$
(whose cardinalities will be determined later), and
apply the following construction:
\begin{eqnarray}
    \tgki &=& \frac{1}{|\cB_i^k|}\sum_{j\in\cB_i^k} \Bigl(g_j(\xki) - g_j(x_0^k) - g_j'(x_0^k)(\xki-x_0^k)\Bigr) + g(x_0^k) + g'(x_0^k)(\xki-x_0^k),
          \label{eqn:g-svrg-correction} \\
    \tJki &=& \frac{1}{|\cS_i^k|}\sum_{j\in\cS_i^k} \Bigl(g'_j(\xki) - g'_j(x_0^k)\Bigr) + g'(x_0^k). 
\label{eqn:J-svrg} 
\end{eqnarray}

Recall the definition that $\tcGki: = M(\xki-\xkie)$. 
In order to complete the convergence analysis, we define a stochastic Lyapunov function
\begin{equation}\label{eqn:lyapunov-def}
R_i^k = \E\left[\Phi(\xki) + c_i\biggl\|\sum_{t=0}^{i-1}\tcGkt\biggr\|^2\right],
\quad k=1,\ldots,K, \quad i=0,\ldots,\tau,
\end{equation}

where the coefficients $c_i$ for $i=0,1,\ldots,\tau$ are obtained through the recursion:
\begin{eqnarray}
c_{\tau} &=& 0, \nonumber \\
c_i &=& c_{i+1}\left(1+\frac{1}{\tau}\right) + \frac{1}{3M\sqrt{|\Bki|}} + \frac{1}{5M|\Ski|}, \quad i=\tau-1,\ldots,0.
\label{eqn:ct-finite-nonsmooth}
\end{eqnarray}

\begin{lemma}\label{lemma:upper-bound} 
Suppose Assumption \ref{assumption:f-cvx} and \ref{assumption:g-lip} hold, then 
for any $x,y\in\dom h$,
\begin{equation}
    f(g(x)) \leq f(g(y) + g'(y)(x-y)) + \frac{\ell_f L_g}{2}\|x-y\|^2.
\end{equation}
\end{lemma}

\begin{proof} 
    By the Lipschitz continuity of $f$ and $g'$, we have
	\begin{eqnarray*}
    f(g(x)) 
    &=&  f\bigl(g(y) + g'(y)(x-y)\bigr) + f(g(x)) - f\bigl(g(y) + g'(y)(x-y)\bigr)\\
    & \leq &  f\bigl(g(y) + g'(y)(x-y)\bigr) + \bigl|f(g(x)) - f\bigl(g(y) + g'(y)(x-y)\bigr)\bigr|\\
	&\leq &f\bigl(g(y) + g'(y)(x-y)\bigr) + \ell_f\bigl\|g(x) - g(y) - g'(y)(x-y)\bigr\|\\
	& \leq & f\bigl(g(y) + g'(y)(x-y)\bigr) + \frac{\ell_f L_g}{2}\|x-y\|^2,
	\end{eqnarray*}
    where the last inequality is due to~\eqref{eqn:g-quadratic-bd}.
\end{proof}

\begin{lemma}
\label{lemma:PG-finite-sum-nonsmooth}
Under Assumptions \ref{assumption:f-cvx} and \ref{assumption:g-lip}, 
the iterates generated by Algorithm~\ref{algo:SVR-PL} satisfy
\begin{eqnarray*}
    \frac{M - \ell_f L_g}{M^2}\bigl\|\cG(\xki)\bigr\|^2 
    &\leq& \frac{2M+\ell_f L_g}{M^2}\bigl\|\widetilde{\cG}(\xki)\bigr\|^2  \\
    && \,+\, 4\ell_f\bigl\|\tgki-g(\xki)\bigr\| + \frac{2\ell_f}{L_g}\bigl\|\tJki-g'(\xki)\bigr\|^2.
\end{eqnarray*}
\end{lemma}

\begin{proof}
For the ease of notation,  we denote 
\begin{eqnarray}
    F(x;\xki) &=& f\bigl(g(\xki) + g'(\xki)(x-\xki)\bigr), \label{eqn:F-def}\\
    \widetilde{F}(x;\xki) &=& f\bigl(\tgki + \tJki(x-\xki)\bigr).
    \label{eqn:tF-def}
\end{eqnarray}
Since both~$f$ and~$h$ are convex (Assumption~\ref{assumption:f-cvx}),
the following two functions are $M$-strongly convex:
\begin{eqnarray}
    && F(x;\xki) + h(x) + \frac{M}{2}\|x-\xki\|^2, \label{eqn:F+h+M} \\
    && \widetilde{F}(x;\xki) + h(x) + \frac{M}{2}\|x-\xki\|^2.
    \label{eqn:tF+h+M} 
\end{eqnarray} 
According to~\eqref{eqn:x-hat-def} and~\eqref{eqn:xkie-def}, $\hat{x}_{i+1}^k$ and $\xkie$ are the minimizers of these two functions respectively. 
Therefore
\begin{eqnarray*}
    F(\hat{x}^k_{i+1};\xki) + h(\hat{x}^k_{i+1}) + \frac{M}{2}\|\hat{x}^k_{i+1}-\xki\|^2 
	& \leq & F(\xkie;\xki) + h(\xkie) + \frac{M}{2}\|\xkie-\xki\|^2  \\
    &&  - \frac{M}{2}\|\hat{x}^k_{i+1}-\xkie\|^2,  
\end{eqnarray*} 
and
\begin{eqnarray*}
    \widetilde{F}(x^k_{i+1};\xki) + h(x^k_{i+1}) + \frac{M}{2}\|x^k_{i+1}-\xki\|^2 
& \leq & \widetilde{F}(\hat{x}^k_{i+1};\xki) + h(\hat{x}^k_{i+1}) + \frac{M}{2}\|\hat{x}^k_{i+1}-\xki\|^2 \\
&& - \frac{M}{2}\|\hat{x}^k_{i+1}-\xkie\|^2. 
\end{eqnarray*} 
Summing the two inequalities above and rearranging the terms, we obtain
\begin{eqnarray}
	\label{lm:PG-finite-sum-3}
	M\|\hat{x}^k_{i+1}-\xkie\|^2 
    &\leq& F(\xkie;\xki)-\widetilde{F}(\xkie;\xki) 
     + \widetilde{F}(\hat{x}^k_{i+1};\xki)-F(\hat{x}^k_{i+1};\xki).
\end{eqnarray}
Using the Lipschitz property of~$f$, we have 
\begin{eqnarray*}
\bigl| F(\xkie;\xki)-\widetilde{F}(\xkie;\xki)\bigr| 
    &=& \left| f\bigl(g(\xki)+g'(\xki)(\xkie-\xki)\bigr) - f\bigl(\tgki+\tJki(\xkie-\xki)\bigr)\right| \\
    & \leq & \ell_f\left\|\bigl(g(\xki) - \tgki\bigr) + \bigl(g'(\xki) - \tJki\bigr)\bigl(\xkie - \xki\bigr)\right\|\\
	& \leq & \ell_f\left(\bigl\|\tgki - g(\xki)\bigr\| + \bigl\|\tJki - g'(\xki)\bigr\|\bigl\|\xkie - \xki\bigr\|\right)\\
    & \leq & \ell_f\left(\bigl\|\tgki - g(\xki)\bigr\| + \frac{1}{2L_g}\bigl\|\tJki - g'(\xki)\bigr\|^2 + \frac{L_g}{2}\bigl\|\xkie-\xki\bigr\|^2 \right).
\end{eqnarray*}
Replacing $\xkie$ in the above inequality with $\hxkie$, we get  
\begin{eqnarray*}
\bigl|F(\hxkie;\xki)-\widetilde{F}(\hxkie;\xki)\bigr| 
	& \leq & \ell_f \left(\bigl\|\tgki - g(\xki)\bigr\| + \frac{1}{2L_g}\bigl\|\tJki - g'(\xki)\bigr\|^2 + \frac{L_g}{2}\bigl\|\hxkie-\xki\bigr\|^2\right).
\end{eqnarray*}
Combining the two bounds above with~\eqref{lm:PG-finite-sum-3} gives
\begin{eqnarray*}
	M\bigl\|\hxkie-\xkie\bigr\|^2 
    & \leq & 2\ell_f\bigl\|\tgki - g(\xki)\bigr\| + \frac{\ell_f}{L_g}\bigl\|\tJki - g'(\xki)\bigr\|^2 \\
    && +\, \frac{\ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2+\frac{\ell_f L_g}{2}\bigl\|\hxkie-\xki\bigr\|^2 .
\end{eqnarray*}
Next, using the fact that $\|a+b\|^2\leq 2\|a\|^2+2\|b\|^2$ and the above inequality, we have
\begin{eqnarray*} 
	M\bigl\|\hxkie-\xki\bigr\|^2] 
    & \leq & 2M\bigl\|\xkie-\xki\bigr\|^2 + 2M\bigl\|\hxkie -\xkie\bigr\|^2 \\
	& \leq & 2M\bigl\|\xkie-\xki\bigr\|^2 + 4\ell_f\bigl\|\tgki - g(\xki)\bigr\| + \frac{2\ell_f}{L_g}\bigl\|\tJki - g'(\xki)\bigr\|^2 \\
	& & + \ell_f L_g\bigl\|\xkie-\xki\bigr\|^2 + \ell_f L_g\bigl\|\hxkie-\xki\bigr\|^2.
\end{eqnarray*}
Rearranging the terms yields 
\begin{eqnarray*}
    (M - \ell_f L_g)\bigl\|\hxkie-\xki\bigr\|^2 
    &\leq& (2M+\ell_f L_g)\bigl\|\xkie-\xki\bigr\|^2  \\
    && +\, 4\ell_f\bigl\|\tgki-g(\xki)\bigr\| 
     \,+\, \frac{2\ell_f}{L_g}\bigl\|\tJki-g'(\xki)\bigr\|^2.
\end{eqnarray*}
Finally, using the definitions $\cG(\xki)=M(\xki-\hxkie)$ and
$\widetilde{\cG}(\xki)=M(\xki-\xkie)$, we obtain the desired result.
\end{proof}

For the ease of notation,  we denote 
\begin{eqnarray}
    F(x;\xki) &=& f\bigl(g(\xki) + g'(\xki)(x-\xki)\bigr), \label{eqn:F-def}\\
    \widetilde{F}(x;\xki) &=& f\bigl(\tgki + \tJki(x-\xki)\bigr).
    \label{eqn:tF-def}
\end{eqnarray}
Since both~$f$ and~$h$ are convex (Assumption~\ref{assumption:f-cvx}),
the following two functions are $M$-strongly convex:
\begin{eqnarray}
    && F(x;\xki) + h(x) + \frac{M}{2}\|x-\xki\|^2, \label{eqn:F+h+M} \\
    && \widetilde{F}(x;\xki) + h(x) + \frac{M}{2}\|x-\xki\|^2.
    \label{eqn:tF+h+M} 
\end{eqnarray} 
According to~\eqref{eqn:x-hat-def} and~\eqref{eqn:xkie-def}, $\hat{x}_{i+1}^k$ and $\xkie$ are the minimizers of these two functions respectively.

Therefore
\begin{eqnarray*}
    F(\hat{x}^k_{i+1};\xki) + h(\hat{x}^k_{i+1}) + \frac{M}{2}\|\hat{x}^k_{i+1}-\xki\|^2 
	& \leq & F(\xkie;\xki) + h(\xkie) + \frac{M}{2}\|\xkie-\xki\|^2  \\
    &&  - \frac{M}{2}\|\hat{x}^k_{i+1}-\xkie\|^2,  
\end{eqnarray*} 
and
\begin{eqnarray*}
    \widetilde{F}(x^k_{i+1};\xki) + h(x^k_{i+1}) + \frac{M}{2}\|x^k_{i+1}-\xki\|^2 
& \leq & \widetilde{F}(\hat{x}^k_{i+1};\xki) + h(\hat{x}^k_{i+1}) + \frac{M}{2}\|\hat{x}^k_{i+1}-\xki\|^2 \\
&& - \frac{M}{2}\|\hat{x}^k_{i+1}-\xkie\|^2. 
\end{eqnarray*}

Summing the two inequalities above and rearranging the terms, we obtain
\begin{eqnarray}
	\label{lm:PG-finite-sum-3}
	M\|\hat{x}^k_{i+1}-\xkie\|^2 
    &\leq& F(\xkie;\xki)-\widetilde{F}(\xkie;\xki) 
     + \widetilde{F}(\hat{x}^k_{i+1};\xki)-F(\hat{x}^k_{i+1};\xki).
\end{eqnarray}

Using the Lipschitz property of~$f$, we have 
\begin{eqnarray*}
\bigl| F(\xkie;\xki)-\widetilde{F}(\xkie;\xki)\bigr| 
    &=& \left| f\bigl(g(\xki)+g'(\xki)(\xkie-\xki)\bigr) - f\bigl(\tgki+\tJki(\xkie-\xki)\bigr)\right| \\
    & \leq & \ell_f\left\|\bigl(g(\xki) - \tgki\bigr) + \bigl(g'(\xki) - \tJki\bigr)\bigl(\xkie - \xki\bigr)\right\|\\
	& \leq & \ell_f\left(\bigl\|\tgki - g(\xki)\bigr\| + \bigl\|\tJki - g'(\xki)\bigr\|\bigl\|\xkie - \xki\bigr\|\right)\\
    & \leq & \ell_f\left(\bigl\|\tgki - g(\xki)\bigr\| + \frac{1}{2L_g}\bigl\|\tJki - g'(\xki)\bigr\|^2 + \frac{L_g}{2}\bigl\|\xkie-\xki\bigr\|^2 \right).
\end{eqnarray*}
Replacing $\xkie$ in the above inequality with $\hxkie$, we get  
\begin{eqnarray*}
\bigl|F(\hxkie;\xki)-\widetilde{F}(\hxkie;\xki)\bigr| 
	& \leq & \ell_f \left(\bigl\|\tgki - g(\xki)\bigr\| + \frac{1}{2L_g}\bigl\|\tJki - g'(\xki)\bigr\|^2 + \frac{L_g}{2}\bigl\|\hxkie-\xki\bigr\|^2\right).
\end{eqnarray*}

Combining the two bounds above with~\eqref{lm:PG-finite-sum-3} gives
\begin{eqnarray*}
	M\bigl\|\hxkie-\xkie\bigr\|^2 
    & \leq & 2\ell_f\bigl\|\tgki - g(\xki)\bigr\| + \frac{\ell_f}{L_g}\bigl\|\tJki - g'(\xki)\bigr\|^2 \\
    && +\, \frac{\ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2+\frac{\ell_f L_g}{2}\bigl\|\hxkie-\xki\bigr\|^2 .
\end{eqnarray*}

\begin{lemma}
	\label{lemma:svr-f-new}
    Suppose Assumption~\ref{assumption:g-lip-finite} holds and $\tgki$ and $\tJki$ are constructed according to~\eqref{eqn:g-svrg-correction} and~\eqref{eqn:J-svrg} respectively, then 
\begin{eqnarray*}
	\E\Bigl[\bigl\|\tgki - g(\xki)\bigr\| \,\big|\, \xki\Bigr] 
        &\leq& \frac{L_g}{2\sqrt{|\cB^k_i|}}\bigl\|\xki - x_0^k\bigr\|^2,\\ 
	\E\Bigl[\bigl\|\tJki - g'(\xki)\bigr\|^2 \,\big|\, \xki\Bigr] 
    &\leq& \frac{L_g^2}{|\cS_i^k|}\bigl\|\xki - x_0^k\bigr\|^2,
\end{eqnarray*}
where $\E[\cdot|\xki]$ denotes conditional expectation given~$\xki$, i.e., expectation with respect to the random indices in $\Bki$ and $\Ski$.
\end{lemma}

\begin{lemma}
\label{lemma: descent-Finite-nonsmooth}
Suppose Assumptions~\ref{assumption:f-cvx} and~\ref{assumption:g-lip-finite} hold and the estimates $\tgkz$, $\tJkz$, $\tgki$ and $\tJki$ in Algorithm~\ref{algo:SVR-PL} are constructed as in~\eqref{eqn:finite-gk0}-\eqref{eqn:J-svrg} respectively.
Then for $k=1,\ldots,K$ and $i=0,\ldots,\tau-1$, 
\begin{eqnarray}
\Phi(\xkie) 
&\leq& \Phi(\xki) - \frac{M - 2\ell_f L_g}{2M^2}\bigl\|\tcGki\bigr\|^2 \nonumber \\
&& +\, 2\ell_f \bigl\|\tgki-g(\xki)\bigr\| + \frac{\ell_f}{2L_g}\bigl\|\tJki-g'(\xki)\bigr\|^2. 
\label{eqn:descent-lemma}
\end{eqnarray}
\end{lemma}

\begin{proof}
By the definition of $\Phi$ in~\eqref{eqn:Phi-def} and Lemma~\ref{lemma:upper-bound}, we have 
\begin{eqnarray}
\Phi(\xkie) & \leq & f(g(\xki) + g'(\xki)(\xkie-\xki)) + \frac{\ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2 + h(\xkie) \nonumber \\
& = &  f\bigl(\tgki + \tJki(\xkie-\xki)\bigr) + h(\xkie) + \frac{M}{2}\bigl\|\xkie-\xki\bigr\|^2
 -\, \frac{M - \ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2 \nonumber \\
& & + \underbrace{f\bigl(g(\xki) + g'(\xki)(\xkie-\xki)\bigr)-f\bigl(\tgki + g'(\xki)(\xkie-\xki)\bigr)}_{T_1}\nonumber\\
& & + \underbrace{f\bigl(\tgki + g'(\xki)(\xkie-\xki)\bigr)-f\bigl(\tgki + \tJki(\xkie-\xki)\bigr)}_{T_2} .
\label{eqn:descent-finite-0}
\end{eqnarray}
According to~\eqref{eqn:xkie-def}, we have
\[
    f\bigl(\tgki + \tJki(\xkie-\xki)\bigr) + h(\xkie) + \frac{M}{2}\bigl\|\xkie-\xki\bigr\|^2 ~\leq~ f(\tgki) + h(\xki).
\]
Therefore,
\begin{eqnarray}
\Phi(\xkie) 
&\leq & f(\tgki) + h(\xki) - \frac{M-\ell_f L_g}{2} \|\xkie-\xki\|^2 + T_1+ T_2 \nonumber\\
&\leq & f(g(\xki)) + h(\xki) - \frac{M-\ell_f L_g}{2} \|\xkie-\xki\|^2 + T_1+ T_2  +  \underbrace{f(\tgki)-f(g(\xki))}_{T_3}\nonumber\\
& = & \Phi(\xki)  - \frac{M-\ell_f L_g}{2} \|\xkie-\xki\|^2 + T_1+ T_2 +T_3. 
\label{eqn:Phi-descent}
\end{eqnarray}
By the Lipschitz property of~$f$, we have
\begin{eqnarray*}
    T_1 \leq \ell_f \bigl\|\tgki-g(\xki)\bigr\|, \qquad
    T_3 \leq \ell_f \bigl\|\tgki-g(\xki)\bigr\|,
\end{eqnarray*}
and
\begin{eqnarray}
T_2 &\leq& \ell_f\bigl\|\bigl(\tJki-g'(\xki)\bigr)(\xkie-\xki)\bigr\|
~\leq~ \ell_f\bigl\|\tJki-g'(\xki)\bigr\|\cdot\bigl\|\xkie-\xki\bigr\| \nonumber\\
&\leq& \frac{\ell_f}{2L_g}\bigl\|\tJki-g'(\xki)\bigr\|^2 + \frac{\ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2.
\label{eqn:descent-lemma-T2}
\end{eqnarray}
Combining the bounds on $T_1$, $T_2$ and $T_3$ and the inequality~\eqref{eqn:Phi-descent} yields
\begin{eqnarray*}
    \Phi(\xkie) 
    &\leq& \Phi(\xki) - \left(\frac{M}{2} - \ell_f L_g\right)\bigl\|\xkie-\xki\bigr\|^2 \\
    && +\, 2\ell_f \bigl\|\tgki-g(\xki)\bigr\| + \frac{\ell_f}{2L_g}\bigl\|\tJki-g'(\xki)\bigr\|^2, 
\end{eqnarray*}
which, upon noticing $\tcGki=-M(\xkie-\xki)$, is equivalent to the
desired result. 
\end{proof}

By the definition of $\Phi$ in~\eqref{eqn:Phi-def} and Lemma~\ref{lemma:upper-bound}, we have 
\begin{eqnarray}
\Phi(\xkie) & \leq & f(g(\xki) + g'(\xki)(\xkie-\xki)) + \frac{\ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2 + h(\xkie) \nonumber \\
& = &  f\bigl(\tgki + \tJki(\xkie-\xki)\bigr) + h(\xkie) + \frac{M}{2}\bigl\|\xkie-\xki\bigr\|^2
 -\, \frac{M - \ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2 \nonumber \\
& & + \underbrace{f\bigl(g(\xki) + g'(\xki)(\xkie-\xki)\bigr)-f\bigl(\tgki + g'(\xki)(\xkie-\xki)\bigr)}_{T_1}\nonumber\\
& & + \underbrace{f\bigl(\tgki + g'(\xki)(\xkie-\xki)\bigr)-f\bigl(\tgki + \tJki(\xkie-\xki)\bigr)}_{T_2} .
\label{eqn:descent-finite-0}
\end{eqnarray}

By the Lipschitz property of~$f$, we have
\begin{eqnarray*}
    T_1 \leq \ell_f \bigl\|\tgki-g(\xki)\bigr\|, \qquad
    T_3 \leq \ell_f \bigl\|\tgki-g(\xki)\bigr\|,
\end{eqnarray*}
and
\begin{eqnarray}
T_2 &\leq& \ell_f\bigl\|\bigl(\tJki-g'(\xki)\bigr)(\xkie-\xki)\bigr\|
~\leq~ \ell_f\bigl\|\tJki-g'(\xki)\bigr\|\cdot\bigl\|\xkie-\xki\bigr\| \nonumber\\
&\leq& \frac{\ell_f}{2L_g}\bigl\|\tJki-g'(\xki)\bigr\|^2 + \frac{\ell_f L_g}{2}\bigl\|\xkie-\xki\bigr\|^2.
\label{eqn:descent-lemma-T2}
\end{eqnarray}

\begin{lemma}
	\label{lemma:Lyapunov-finite-nonsmooth}
Suppose Assumptions~\ref{assumption:f-cvx} and~\ref{assumption:g-lip-finite} hold and the estimates $\tgkz$, $\tJkz$, $\tgki$ and $\tJki$ in Algorithm~\ref{algo:SVR-PL} are constructed as in~\eqref{eqn:finite-gk0}-\eqref{eqn:J-svrg} respectively.
In addition, we assume $M\geq 4\ell_f L_g$ and $\gamma>0$.
Then for each $k=1,\ldots,K$,
\begin{equation}\label{lm:Lyapunov-finite-nonsmooth-1}
	\sum_{i=0}^{\tau-1}\E\Bigl[\bigl\|\cGki\bigr\|^2\Bigr] 
    ~\leq~  \frac{R^k_0-R^k_\tau}{\gamma}  
    ~=~ \frac{\E[\Phi(x_0^k)]-\E[\Phi(x_0^{k+1})]}{\gamma}.
\end{equation}
\end{lemma}

For the ease of notation, we write the stochastic Lyapunov function as
$$R^k_i = \E\bigl[\Phi(\xki) + c_i\|G_i^k\|^2\bigr],$$
where
\begin{equation}\label{eqn:Gki-def}
    \Gki = \sum_{t=0}^{i-1}\tcGkt = -M(\xki - x_0^k).
\end{equation}
In particular, we have $G_{0}^k = -M(x_0^k-x_0^k) = 0$.
Moreover, we have 
\begin{eqnarray}
	\E\bigl[\|G_{i+1}^k\|^2\bigr] 
    &=& \E\bigl[\|G_{i}^k + \tcGki\|^2\bigr]   \nonumber \\
    &\leq& \left(1+\frac{1}{\tau}\right)\E\bigl[\|G_{i}^k\|^2\bigr] + (1+\tau)\E\bigl[\|\tcGki\|^2\bigr]. 
\label{eqn:Gki-tcG}
\end{eqnarray}

Combining Lemmas~\ref{lemma:PG-finite-sum-nonsmooth} 
and~\ref{lemma: descent-Finite-nonsmooth} yields
\begin{eqnarray*}
\E\bigl[\Phi(\xkie)\bigr] 
    &\leq& \E\bigl[\Phi(\xki)\bigr] - \frac{M - 2\ell_f L_g}{2M^2}\E\bigl[\bigl\|\tcGki\bigr\|^2\bigr] + \left(\frac{\ell_f L_g}{\sqrt{|\cB_i^k|}}+\frac{\ell_f L_g}{2|\cS_i^k|}\right)\E\bigl[\|\xki-x_0^k\|^2\bigr] \\
    &=& \E\bigl[\Phi(\xki)\bigr] - \frac{M - 2\ell_f L_g}{2M^2}\E\bigl[\bigl\|\tcGki\bigr\|^2\bigr] + \frac{1}{M^2}\left(\frac{\ell_f L_g}{\sqrt{|\cB_i^k|}}+\frac{\ell_f L_g}{2|\cS_i^k|}\right)\E\bigl[\|G^k_i\|^2\bigr],
\end{eqnarray*}
where in the last equality we used~\eqref{eqn:Gki-def}.

Next, combining Lemma~\ref{lemma:PG-finite-sum-nonsmooth} with Lemmas~\ref{lemma:svr-f-new} yields
\begin{eqnarray*}
    \frac{M - \ell_f L_g}{M^2}\E\bigl[\|\cGki\|^2\bigr]
    &\leq&
    \frac{2M+\ell_f L_g}{M^2}\E\bigl[\|\tcGki\|^2\bigr] 
     + \left( \frac{2\ell_f L_g}{\sqrt{|\cB_i^k|}} + \frac{2\ell_f L_g}{|\cS_i^k|} \right) \E\bigl[\|\xki-\xkz\|^2\bigr].
\end{eqnarray*}
Using the equality $G^k_i=-M(\xki-\xkz)$ and the assumption $M\geq 4\ell_f L_g$, the above inequality implies
\begin{eqnarray}
    \frac{3}{4M}\E\bigl[\|\cGki\|^2\bigr]
    &\leq&
    \frac{9}{4M}\E\bigl[\|\tcGki\|^2\bigr] 
     +\, \frac{1}{2M} \left( \frac{1}{\sqrt{|\cB_i^k|}} + \frac{1}{|\cS_i^k|} \right) \E\bigl[\|G^k_i\|^2\bigr].
    \label{eqn:cG-bound}
\end{eqnarray}

Multiplying both sides of~\eqref{eqn:cG-bound} by $\left(\frac{1}{4M}-c_{i+1}(1+\tau)\right)\big/\frac{9}{4M}$, which is positive by the assumption $\gamma>0$, and adding the resulting inequality to~\eqref{eqn:lyapunov-descent}, we get
\begin{eqnarray}
%\label{lm:Lyapunov-finite-nonsmooth-2}
\E\bigl[\Phi(\xkie)+c_{i+1}\|G_{i+1}^k\|^2\bigr] 
&\leq& \E\left[\Phi(\xki)+\left( c_{i+1}\left(1+\frac{1}{\tau}\right)+ \frac{1}{3M\sqrt{|\cB_i^k|}} + \frac{1}{5M|\cS_i^k|}\right)\|G_i^k\|^2\right] \nonumber\\
	&& -\frac{1}{3}\left(\frac{1}{4M} - c_{i+1}(1+\tau)\right)\E[\|\cGki\|^2].\nonumber
\end{eqnarray}

\begin{lemma}
\label{lemma:gamma-nonsmooth}
    If we choose 
    $\tau = \bigl\lceil\frac{1}{2}N^{1/5}-1\bigr\rceil$,
    $|\cB_i^k| = \bigr\lceil 4N^{4/5}\bigr\rceil$ and
    $|\cS_i^k| = \bigr\lceil N^{2/5}\bigr\rceil$ for $i=1,\ldots,\tau-1$,
    then $\gamma  \geq \frac{1}{15M}$.
\end{lemma}

	Summing up the inequality \eqref{lm:Lyapunov-finite-nonsmooth-1} 
    over~$k$ from~$1$ to~$K$ and using the fact $\Phi(x^K_\tau)>\Phi_*$, we get
	\begin{eqnarray*}
		\sum_{k=1}^K\sum_{i=0}^{\tau-1}\E\bigl[\|\cGki\|^2\bigr] ~\leq~ \frac{\Phi(x_0^1) - \Phi(x^*)}{\gamma}.
	\end{eqnarray*}
	By the random choice of the output $x_{i^*}^{k^*}$, we can get the inequality \eqref{eqn:cvg-svr-pl-nonsmooth-1}.
